import{_ as s,a0 as i,w as u,s as r,ao as c,I as o,x as p,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"Linux有問必答：如何使用tcpdump來捕獲TCP SYN，ACK和FIN包 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何使用tcpdump來捕獲TCP SYN，ACK和FIN包 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何使用tcpdump來捕獲TCP SYN，ACK和FIN包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何使用tcpdump來捕獲TCP SYN，ACK和FIN包 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140915 Linux FAQs with Answers--How to capture TCP SYN, ACK and FIN packets with tcpdump","title":"Linux有問必答：如何使用tcpdump來捕獲TCP SYN，ACK和FIN包","tag":"201410","desc":""},"relativePath":"201410/20140915 Linux FAQs with Answers--How to capture TCP SYN, ACK and FIN packets with tcpdump.md","filePath":"[post].md"}'),d={name:"201410/20140915 Linux FAQs with Answers--How to capture TCP SYN, ACK and FIN packets with tcpdump.md"};function m(l,t,C,T,f,N){const e=i("Link");return u(),r("div",null,[t[11]||(t[11]=c(`<h1 id="linux有問必答-如何使用tcpdump來捕獲tcp-syn-ack和fin包" tabindex="-1">Linux有問必答：如何使用tcpdump來捕獲TCP SYN，ACK和FIN包 <a class="header-anchor" href="#linux有問必答-如何使用tcpdump來捕獲tcp-syn-ack和fin包" aria-label="Permalink to “Linux有問必答：如何使用tcpdump來捕獲TCP SYN，ACK和FIN包”">​</a></h1><blockquote><p><strong>問題</strong>：我想要監控TCP連接活動（如，建立連接的三次握手，以及斷開連接的四次握手）。要完成此事，我只需要捕獲TCP控制包，如SYN，ACK或FIN標記相關的包。我怎樣使用tcpdump來僅僅捕獲TCP SYN，ACK和/或FYN包？</p></blockquote><p>作為業界標準的捕獲工具，tcpdump提供了強大而又靈活的包過濾功能。作為tcpdump基礎的libpcap包捕獲引擎支持標準的包過濾規則，如基於5重包頭的過濾（如基於源/目的IP地址/端口和IP協議類型）。</p><p>tcpdump/libpcap的包過濾規則也支持更多通用分組表達式，在這些表達式中，包中的任意字節範圍都可以使用關係或二進制操作符進行檢查。對於字節範圍表達，你可以使用以下格式：</p><pre><code>proto [ expr : size ]
</code></pre><p>“proto”可以是熟知的協議之一（如ip，arp，tcp，udp，icmp，ipv6），“expr”表示與指定的協議頭開頭相關的字節偏移量。有我們熟知的直接偏移量如tcpflags，也有取值常量如tcp-syn，tcp-ack或者tcp-fin。“size”是可選的，表示從字節偏移量開始檢查的字節數量。</p><p>使用這種格式，你可以像下面這樣過濾TCP SYN，ACK或FIN包。</p><p>只捕獲TCP SYN包：</p><pre><code> # tcpdump -i &lt;interface&gt; &quot;tcp[tcpflags] &amp; (tcp-syn) != 0&quot; 
</code></pre><p>只捕獲TCP ACK包：</p><pre><code># tcpdump -i &lt;interface&gt; &quot;tcp[tcpflags] &amp; (tcp-ack) != 0&quot;
</code></pre><p>只捕獲TCP FIN包：</p><pre><code># tcpdump -i &lt;interface&gt; &quot;tcp[tcpflags] &amp; (tcp-fin) != 0&quot;
</code></pre><p>之捕獲TCP SYN或ACK包：</p><pre><code> # tcpdump -r &lt;interface&gt; &quot;tcp[tcpflags] &amp; (tcp-syn|tcp-ack) != 0&quot; 
</code></pre><p><img src="https://farm4.staticflickr.com/3923/15050566798_db14aea9a9_z.jpg" alt=""></p><hr>`,17)),o("p",null,[t[1]||(t[1]=p("via: ",-1)),a(e,{href:"http://ask.xmodulo.com/capture-tcp-syn-ack-fin-packets-tcpdump.html"},{default:n(()=>[...t[0]||(t[0]=[p("http://ask.xmodulo.com/capture-tcp-syn-ack-fin-packets-tcpdump.html",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=p("譯者：",-1)),a(e,{href:"https://github.com/GOLinux"},{default:n(()=>[...t[2]||(t[2]=[p("GOLinux",-1)])]),_:1}),t[5]||(t[5]=p(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[3]||(t[3]=[p("wxy",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=p("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[p("LCTT",-1)])]),_:1}),t[9]||(t[9]=p(" 原創翻譯，",-1)),a(e,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[p("Linux中國",-1)])]),_:1}),t[10]||(t[10]=p(" 榮譽推出",-1))])])}const _=s(d,[["render",m]]);export{P as __pageData,_ as default};
